public class RequiredChoiceProbe61 {
 public static Map<String,Object> observe(String shape,Boolean supplied,Boolean systemMode) {
  Schema.SObjectType token=RequiredChoice__c.SObjectType;
  Id realId=token.getDescribe().getRecordTypeInfosByDeveloperName().get('Alpha').getRecordTypeId();
  SObject row=makeRow(token,shape,supplied,realId);
  Map<String,Object> result=new Map<String,Object>{'shape'=>shape,'requiredSupplied'=>supplied,'mode'=>systemMode?'SYSTEM_MODE':'default'};
  List<Database.SaveResult> saved=systemMode?Database.insert(new List<SObject>{row},false,AccessLevel.SYSTEM_MODE):Database.insert(new List<SObject>{row},false);
  List<Object> errors=new List<Object>();
  for(Database.Error error:saved[0].getErrors()) errors.add(new Map<String,Object>{'status'=>String.valueOf(error.getStatusCode()),'fields'=>error.getFields(),'message'=>project(error.getMessage(),realId)});
  result.put('partial',new Map<String,Object>{'success'=>saved[0].isSuccess(),'idPresent'=>saved[0].getId()!=null,'errors'=>errors});
  SObject throwing=makeRow(token,shape,supplied,realId);
  try {
   if(systemMode)Database.insert(new List<SObject>{throwing},true,AccessLevel.SYSTEM_MODE);else Database.insert(new List<SObject>{throwing},true);
   result.put('throwing',new Map<String,Object>{'success'=>true,'idPresent'=>throwing.Id!=null});
  }catch(Exception error) {
   Map<String,Object> details=new Map<String,Object>{'success'=>false,'type'=>error.getTypeName(),'message'=>project(error.getMessage(),realId)};
   if(error instanceof DmlException){DmlException de=(DmlException)error;details.put('firstStatus',String.valueOf(de.getDmlStatusCode(0)));details.put('firstMessage',project(de.getDmlMessage(0),realId));List<String> names=new List<String>();List<Schema.SObjectField> fields=de.getDmlFields(0);details.put('firstFieldsNull',fields==null);if(fields!=null)for(Schema.SObjectField field:fields)names.add(String.valueOf(field));details.put('firstFields',names);details.put('firstFieldNames',de.getDmlFieldNames(0));}
   result.put('throwing',details);
  }
  return result;
 }
 private static SObject makeRow(Schema.SObjectType token,String shape,Boolean supplied,Id realId) {
  SObject row=token.newSObject();if(supplied)row.put('RequiredNote__c','supplied');
  if(shape=='null')row.put('RecordTypeId',null);if(shape=='real')row.put('RecordTypeId',realId);
  return row;
 }
 private static String project(String message,Id realId){return message.replace(String.valueOf(realId),'<RT:Alpha>').replace(String.valueOf(realId).substring(0,15),'<RT:Alpha>');}
}

